\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}
\usepackage{booktabs}
\usepackage{listings}

\title{Pollinator Visitation in Restored Meadow Strips}
\author{L.~Brandt, O.~Ferreira, and K.~Sato}
\date{May 2026}

\begin{document}
\maketitle

\section{Overview}
Visitation was recorded in ten restored strips over twelve weeks;
Table~\ref{table:visitation} summarises the pooled counts.

\begin{table}[h]
\centering
\begin{tabular}{lc}
\toprule
Visitor group & Visits recorded \\
\midrule
Bumble bees & 1{,}214 \\
Solitary bees & 986 \\
Hoverflies & 743 \\
\bottomrule
\end{tabular}
\caption{Pooled pollinator visits across all strips.}
\label{table:visitation}
\end{table}

\input{chapters/analysis}

\appendix
\section{Processing Script}
The stub generator below produced the table skeletons used during
drafting; it is reproduced exactly as run.

\begin{lstlisting}
# Build the LaTeX stub for each results table.
def table_stub(key):
    return ("\\begin{table}\n"
            "\\label{table:" + key + "}\n"
            "\\end{table}")

for key in ["visitation", "abundance", "traits"]:
    print(table_stub(key))

note = "see Table \\ref{table:visitation} for the raw counts"
\end{lstlisting}

\end{document}

\section{Strip-Level Analysis}
Counts per strip appear in Table~\ref{table:abundance}, and the
trait means used in the mixture model appear in
Table~\ref{table:traits}; site covariates are listed in
Table~\ref{tab:site}. Cross-checks against
Table~\ref{table:visitation} found no transcription drift.

\begin{table}[h]
\centering
\begin{tabular}{lc}
\toprule
Strip & Visits per hour \\
\midrule
North 1 & 14.2 \\
North 2 & 12.8 \\
South 1 & 15.6 \\
\bottomrule
\end{tabular}
\caption{Visitation rates by strip.}
\label{table:abundance}
\end{table}

\begin{table}[h]
\centering
\begin{tabular}{lc}
\toprule
Trait & Mean \\
\midrule
Corolla depth (mm) & 8.4 \\
Nectar sugar (\%) & 31.2 \\
\bottomrule
\end{tabular}
\caption{Floral trait means for the three dominant forbs.}
\label{table:traits}
\end{table}

\begin{table}[h]
\centering
\begin{tabular}{lc}
\toprule
Site & Area (ha) \\
\midrule
North & 2.6 \\
South & 3.1 \\
\bottomrule
\end{tabular}
\caption{Surveyed sites and their restored areas.}
\label{tab:site}
\end{table}

Composition differences between strips were modest and tracked
the forb gradient described above.

